    h, w = len(grid), len(grid[0])
    overall = Counter(v for row in grid for v in row)
    background = overall.most_common(1)[0][0]

    # Separator lines are the rows and columns dominated by a color other
    # than the interior background.
    rows = []
    row_colors = []
    for r in range(h):
        color, count = Counter(grid[r]).most_common(1)[0]
        if color != background and count > w // 2:
            rows.append(r)
            row_colors.append(color)

    cols = []
    col_colors = []
    for c in range(w):
        color, count = Counter(grid[r][c] for r in range(h)).most_common(1)[0]
        if color != background and count > h // 2:
            cols.append(c)
            col_colors.append(color)

    if len(rows) < 2 or len(cols) < 2:
        return [[background]]

    line_color = Counter(row_colors + col_colors).most_common(1)[0][0]

    marks = []
    for i, r in enumerate(rows):
        for j, c in enumerate(cols):
            v = grid[r][c]
            if v != line_color and v != background:
                marks.append((i, j))
    if not marks:
        return [[background]]

    r0, r1 = min(i for i, _ in marks), max(i for i, _ in marks)
    c0, c1 = min(j for _, j in marks), max(j for _, j in marks)

    output = []
    for i in range(r0, r1):
        out_row = []
        for j in range(c0, c1):
            vals = (
                grid[rows[i]][cols[j]],
                grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]],
                grid[rows[i + 1]][cols[j + 1]],
            )
            if vals[0] != line_color and all(v == vals[0] for v in vals):
